+package com.example;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.Text;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.Div;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.shared.HasValidationProperties;
+import com.vaadin.flow.component.HasValue;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.provider.ListDataProvider;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.dom.DomEvent;
+import com.vaadin.flow.dom.DomListenerRegistration;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+import tools.jackson.databind.JsonNode;
+
+/**
+ * The contact view: a form to send a message and a list of the messages sent
+ * so far.
+ */
+@Route("contact")
+public class ContactView extends Div implements BeforeLeaveObserver {
+
+    /* The HTML5 (WHATWG) e-mail validation pattern. */
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(
+            "^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$");
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final MessageStore store;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<Message> grid = new Grid<>(Message.class, false);
+
+    private DomListenerRegistration enterListener;
+
+    public ContactView(MessageStore store) {
+        this.store = store;
+        buildUi();
+        addAttachListener(event -> {
+            refreshGrid();
+            registerEnterHandler();
+        });
+    }
+
+    private void buildUi() {
+        H1 heading = new H1("Contact");
+        RouterLink aboutLink = new RouterLink("About", AboutView.class);
+
+        nameField.setValueChangeMode(ValueChangeMode.EAGER);
+        emailField.setValueChangeMode(ValueChangeMode.EAGER);
+        phoneField.setValueChangeMode(ValueChangeMode.EAGER);
+        messageField.setValueChangeMode(ValueChangeMode.EAGER);
+
+        sendButton.addClickListener(event -> doSend());
+
+        nameField.addValueChangeListener(event -> onFieldEdited(nameField));
+        emailField.addValueChangeListener(event -> onFieldEdited(emailField));
+        phoneField.addValueChangeListener(event -> onFieldEdited(phoneField));
+        messageField.addValueChangeListener(event -> onFieldEdited(messageField));
+
+        grid.addColumn(Message::name).setHeader("Name");
+        grid.addColumn(Message::message).setHeader("Message");
+        grid.addColumn(Message::email).setHeader("Email");
+        grid.addColumn(Message::phone).setHeader("Phone");
+
+        Div form = new Div(nameField, emailField, phoneField, messageField, sendButton);
+        form.getStyle().set("display", "flex").set("flex-direction", "column")
+                .set("gap", "0.5rem").set("max-width", "24rem");
+
+        add(heading, aboutLink, form, grid);
+    }
+
+    private void onFieldEdited(HasValue<?, String> field) {
+        clearInvalid(field);
+        sendButton.setEnabled(true);
+    }
+
+    private void registerEnterHandler() {
+        if (enterListener != null) {
+            return;
+        }
+        UI ui = getUI().orElse(null);
+        if (ui == null) {
+            return;
+        }
+        enterListener = ui.getElement().addEventListener("keydown", this::handleKeydown);
+        addDetachListener(event -> {
+            enterListener.remove();
+            enterListener = null;
+        });
+    }
+
+    private void handleKeydown(DomEvent event) {
+        if (!"keydown".equals(event.getType())) {
+            return;
+        }
+        if (isEnterKey(event.getEventData())) {
+            doSend();
+        }
+    }
+
+    private static boolean isEnterKey(JsonNode data) {
+        if (data == null) {
+            return false;
+        }
+        for (String field : new String[] { "key", "event.key", "code" }) {
+            JsonNode node = data.get(field);
+            if (node != null && node.isTextual() && "Enter".equalsIgnoreCase(node.textValue())) {
+                return true;
+            }
+        }
+        return data.toString().contains("\"Enter\"");
+    }
+
+    private void doSend() {
+        if (!validate()) {
+            return;
+        }
+
+        Message sent = new Message(
+                trimToEmpty(nameField),
+                trimToEmpty(emailField),
+                trimToEmpty(phoneField),
+                trimToEmpty(messageField));
+        store.add(sent);
+        refreshGrid();
+
+        nameField.setValue("");
+        emailField.setValue("");
+        phoneField.setValue("");
+        messageField.setValue("");
+
+        Notification.show("Message sent");
+
+        /*
+         * Disabling happens after clearing the fields: clearing fires the value
+         * change listeners (which re-enable the button), so the disabling must be
+         * the last word.
+         */
+        sendButton.setEnabled(false);
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+
+        String name = trimToEmpty(nameField);
+        String email = trimToEmpty(emailField);
+        String phone = trimToEmpty(phoneField);
+        String message = trimToEmpty(messageField);
+
+        if (name.isEmpty()) {
+            markInvalid(nameField, "Name is required");
+            valid = false;
+        } else {
+            clearInvalid(nameField);
+        }
+
+        if (!email.isEmpty() && !EMAIL_PATTERN.matcher(email).matches()) {
+            markInvalid(emailField, "Enter a valid e-mail address");
+            valid = false;
+        } else if (email.isEmpty() && phone.isEmpty()) {
+            markInvalid(emailField, "Give an e-mail address or a phone number");
+            valid = false;
+        } else {
+            clearInvalid(emailField);
+        }
+
+        if (message.isEmpty()) {
+            markInvalid(messageField, "Message is required");
+            valid = false;
+        } else if (message.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(messageField, "Message must be at most 500 characters");
+            valid = false;
+        } else {
+            clearInvalid(messageField);
+        }
+
+        return valid;
+    }
+
+    private void markInvalid(HasValue<?, String> field, String message) {
+        if (field instanceof HasValidationProperties validation) {
+            validation.setInvalid(true);
+            validation.setErrorMessage(message);
+        }
+    }
+
+    private void clearInvalid(HasValue<?, String> field) {
+        if (field instanceof HasValidationProperties validation) {
+            validation.setInvalid(false);
+            validation.setErrorMessage(null);
+        }
+    }
+
+    private void refreshGrid() {
+        grid.setItems(new ListDataProvider<>(store.getMessages()));
+    }
+
+    private static String trimToEmpty(HasValue<?, String> field) {
+        String value = field.getValue();
+        return value == null ? "" : value.trim();
+    }
+
+    private boolean hasAnyInput() {
+        return !trimToEmpty(nameField).isEmpty()
+                || !trimToEmpty(emailField).isEmpty()
+                || !trimToEmpty(phoneField).isEmpty()
+                || !trimToEmpty(messageField).isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasAnyInput()) {
+            return;
+        }
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+        if (action != null) {
+            showUnsavedChangesDialog(action);
+        }
+    }
+
+    private void showUnsavedChangesDialog(BeforeLeaveEvent.ContinueNavigationAction action) {
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Unsaved changes");
+
+        Button keepEditing = new Button("Keep editing", event -> {
+            action.cancel();
+            dialog.close();
+        });
+        Button discard = new Button("Discard", event -> {
+            dialog.close();
+            action.proceed();
+        });
+
+        dialog.add(new Text("You have unsaved changes. Leave this page?"), keepEditing, discard);
+        dialog.open();
+    }
+}
