+package com.example;
+
+import java.util.ArrayList;
+import java.util.List;
+import java.util.Map;
+import java.util.concurrent.ConcurrentHashMap;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Component;
+
+import com.vaadin.flow.component.UI;
+
+/**
+ * In-memory store for the messages sent through the contact form.
+ *
+ * <p>
+ * Messages are kept per {@link UI}, so the list survives leaving the view and
+ * coming back (the view is re-created on each navigation, the UI is not) but a
+ * brand new session starts with an empty list. Nothing is written to disk.
+ */
+@Component
+public class MessageStore {
+
+    private final Map<UI, List<Message>> messagesByUi = new ConcurrentHashMap<>();
+
+    /**
+     * Stores a message so it becomes the most recent one.
+     */
+    public void add(Message message) {
+        forUi().add(0, message);
+    }
+
+    /**
+     * @return the messages sent in the current UI, newest first.
+     */
+    public List<Message> getMessages() {
+        return new ArrayList<>(messagesByUi.getOrDefault(ui(), List.of()));
+    }
+
+    private List<Message> forUi() {
+        return messagesByUi.computeIfAbsent(ui(), k -> new CopyOnWriteArrayList<>());
+    }
+
+    private static UI ui() {
+        UI ui = UI.getCurrent();
+        if (ui == null) {
+            throw new IllegalStateException("No UI is available in the current thread");
+        }
+        return ui;
+    }
+}
